  if (sy > barY - barH && sy < barY) {
    const prog = Math.min(1, (Math.sin(t*0.4)*0.3+0.6));
    statusBar = sx < 480 * prog ? 0.8 : 0.1;
    if (Math.abs(sy - barY + barH/2) < 0.5) statusBar *= 1.5;
  }
  let textLines = 0;
  for (let i = 0; i < 3; i++) {
