    if (Math.abs(sy - tlY) < 5) {
      const hash = Math.sin(sx*0.8+i*13.7+t*0.1)*43758.5453 % 1;
      const charMask = (hash > 0.3 && hash < 0.8) ? 0.2 : 0;
      textLines = Math.max(textLines, charMask * (1 - Math.abs(sy-tlY)/5));
    }
  }
  let sidePanel = 0;
  if (sx > 430) {
    const pw = sx - 430;
    const stripes = Math.sin(pw*0.5+t*0.8)*0.5+0.5;
    sidePanel = stripes * 0.12 * Math.exp(-pw*0.02);
  }
  const miniChart = (sx > 10 && sx < 70 && sy > 80 && sy < 140) ? 
    (Math.sin(sx*0.2)*20 + Math.cos(sx*0.15+t)*15 > (140-sy)*0.6 ? 0.35 : 0) * 
    Math.min(1, Math.min(sx-10, 70-sx, sy-80, 140-sy)/3) : 0;
  const blend = reaction*0.55 + cell*0.15 + neuralLayer*0.12 + grid*0.05 + statusBar*0.06 + textLines*0.03 + sidePanel*0.02 + miniChart*0.02;
  const v = blend*0.5+0.5;
  const pal = [[5,5,25],[10,30,90],[0,180,255],[0,255,200],[255,255,80],[255,100,50],[255,30,120],[180,0,255],[40,0,80],[5,5,25]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge = Math.abs(reaction)>0.65 ? 1.3 : (Math.abs(neuralLayer)>0.15 ? 1.2 : 1.0);
  const neon = v > 0.4 && v < 0.7 ? 1.15 : 1.0;
  const boost = lum * edge * neon;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*boost)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*boost)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*boost)|0
  ];
}
